fn provider(locale: &str) -> Option<&'static Provider> {
    match locale {
        "es_AR" => Some(&ES_AR),
        "es_ES" => Some(&ES_ES),
        "es_PE" => Some(&ES_PE),
        "es_VE" => Some(&ES_VE),
        "pt_BR" => Some(&PT_BR),
        "pt_PT" => Some(&PT_PT),
        _ => None,
    }
}

pub(super) fn company(random: &FakerRandom, locale: &str) -> Option<String> {
    let provider = provider(locale)?;
    let template = provider.templates[random.usize(..provider.templates.len())];
    Some(
        template
            .iter()
            .map(|part| match part {
                Text(text) => *text,
                Prefix => random.sample(provider.prefixes),
                Surname => random.sample(provider.names),
                Suffix => random.sample(provider.suffixes),
            })
            .collect(),
    )
}

pub(super) fn prefixes(locale: &str) -> Option<&'static [&'static str]> {
    let prefixes = provider(locale)?.prefixes;
    (!prefixes.is_empty()).then_some(prefixes)
}

pub(super) fn suffixes(locale: &str) -> Option<&'static [&'static str]> {
    Some(provider(locale)?.suffixes)
}

pub(in crate::database::eloquent::factories::faker) fn surnames(
    locale: &str,
) -> Option<&'static [&'static str]> {
    provider(locale).map(|provider| provider.names)
}
